import * as THREE from 'three';
import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
const $=id=>document.getElementById(id), view=$('view');
const scene=new THREE.Scene(); scene.background=new THREE.Color('#0b0d11');
const camera=new THREE.PerspectiveCamera(35,1,.03,80); camera.position.set(4.6,2.8,7.8);
const renderer=new THREE.WebGLRenderer({canvas:$('canvas'),antialias:true}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.5)); renderer.toneMapping=THREE.ACESFilmicToneMapping;
scene.add(new THREE.HemisphereLight('#dce6f5','#11131b',2)); const key=new THREE.DirectionalLight('#fff0cf',4); key.position.set(-4,7,5); scene.add(key); const rim=new THREE.DirectionalLight('#6e9fff',3); rim.position.set(4,4,-4); scene.add(rim);
const ground=new THREE.Mesh(new THREE.CircleGeometry(2.4,96),new THREE.MeshStandardMaterial({color:'#171a20',metalness:.75,roughness:.3})); ground.rotation.x=-Math.PI/2; ground.position.y=-.045; scene.add(ground);
const orbit=new OrbitControls(camera,renderer.domElement); orbit.enableDamping=true; orbit.target.set(0,1.6,0);
function resize(){let w=view.clientWidth,h=view.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()} new ResizeObserver(resize).observe(view);resize();
new GLTFLoader().load('/assets/exhibit.glb',g=>{scene.add(g.scene);$('loading').classList.add('done')},undefined,e=>{$('loading').textContent='模型载入失败：'+e.message});
function loop(){requestAnimationFrame(loop);orbit.update();renderer.render(scene,camera)} loop();
